'use strict';
function field(name,label,type='text',value='',extra=''){return `<label class="field">${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function downloadFile(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function csvFile(name,rows){downloadFile(new Blob([rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv'}),name);}
async function showTool(title,load){modal(title,'<p role="status">Loading…</p>');try{await load();}catch(e){if(e.status===401){$('#dialog').close();login();return;}$('#modalBody').innerHTML=errorHTML(e);if($('#retry'))$('#retry').onclick=()=>showTool(title,load);}}
function appendActions(items){const bar=document.createElement('div');bar.className='toolbar tool-actions';for(const [label,fn] of items){const b=document.createElement('button');b.className='btn';b.textContent=label;b.onclick=()=>fn();bar.append(b);}$('#content').prepend(bar);}
let variantRows=[],variantFields=[];
const originalCategoryFields=categoryFields;
categoryFields=function(saved){originalCategoryFields(saved);const cat=categories.find(c=>String(c.id)===$('#category').value);variantFields=(cat?.attributes||[]).filter(a=>a.is_variant===true);variantRows=structuredClone(saved.product_variants||[]);$('#variantEditor')?.remove();if(!variantFields.length)syncVariantBase();if(variantFields.length){for(const f of variantFields){const input=document.getElementsByName('attr:'+f.attribute_key)[0];if(input){input.required=false;input.closest('label').hidden=true;}}const block=document.createElement('div');block.id='variantEditor';block.className='panel';$('#categoryFields').after(block);renderVariants();}for(const input of document.querySelectorAll('[name^="slot:"]')){const required=input.required;const caption=input.closest('label').firstChild;if(caption?.nodeType===3)caption.textContent=caption.textContent.replace(' · HTTPS image URL',' · Photo');input.type='hidden';input.required=false;const upload=document.createElement('input');upload.type='file';upload.accept='image/jpeg,image/png,image/webp';upload.dataset.slotFile=input.name;upload.dataset.required=String(required);upload.setAttribute('aria-label',input.closest('label').textContent+' photo');input.after(upload);if(input.value){const small=document.createElement('small');small.textContent='Saved photo available. Choose a file to replace it.';upload.after(small);}}};
function renderVariants(){
 const holder=$('#variantEditor');if(!holder)return;
 if(!variantRows.length){const saved=editing?.product_data||{};variantRows.push({variant_values:Object.fromEntries(variantFields.map(f=>[f.attribute_key,saved.product_attributes?.[f.attribute_key]||''])),sku:saved.sku||'',price:$('#catalogForm [name=price]').value,stock:$('#catalogForm [name=stock]').value,compare_price:$('#catalogForm [name=compare_price]').value});}
 const multiple=variantRows.length>1;
 holder.innerHTML=`<div class="sectionhead"><h2>Product options</h2><button type="button" class="btn" id="addVariant">＋ Add another option</button></div><p class="muted">Choose ${esc(variantFields.map(f=>f.label.toLowerCase()).join(' / '))} for this product. Selling only one option? Complete the first card. Add another only for a different colour, size or finish.</p><div class="option-cards">${variantRows.map((v,i)=>`<fieldset class="option-card"><legend>Option ${i+1}</legend>${variantFields.map(f=>`<label class="field">${esc(f.label)} <small>Required</small>${f.options?.length?`<select data-v="${i}" data-key="${esc(f.attribute_key)}" required><option value="">Choose ${esc(f.label)}</option>${f.options.map(o=>`<option ${String(v.variant_values?.[f.attribute_key])===String(typeof o==='object'?o.value:o)?'selected':''} value="${esc(typeof o==='object'?o.value:o)}">${esc(typeof o==='object'?o.label||o.value:o)}</option>`).join('')}</select>`:`<input data-v="${i}" data-key="${esc(f.attribute_key)}" value="${esc(v.variant_values?.[f.attribute_key]||'')}" required>`}</label>`).join('')}<label class="field">Seller SKU <small>Required · your unique item code</small><input data-v="${i}" data-prop="sku" value="${esc(v.sku||'')}" placeholder="Example: CHAIR-BROWN-01" required></label>${multiple?['price','compare_price','stock'].map(k=>`<label class="field">${{price:'Selling price ₹',compare_price:'Compare price ₹',stock:'Available stock'}[k]} <small>${k==='compare_price'?'Optional':'Required'}</small><input data-v="${i}" data-prop="${k}" type="number" min="${k==='price'?'0.01':'0'}" step="${k==='stock'?'1':'0.01'}" ${k==='compare_price'?'':'required'} value="${esc(v[k]??'')}"></label>`).join(''):''}${multiple?`<button type="button" class="btn" data-remove-variant="${i}">Remove option ${i+1}</button>`:''}</fieldset>`).join('')}</div>`;
 holder.querySelectorAll('[data-v]').forEach(el=>el.oninput=()=>{const row=variantRows[Number(el.dataset.v)];if(el.dataset.key){row.variant_values||={};row.variant_values[el.dataset.key]=el.value;}else row[el.dataset.prop]=el.value;syncVariantBase();});
 holder.querySelectorAll('[data-remove-variant]').forEach(b=>b.onclick=()=>{variantRows.splice(Number(b.dataset.removeVariant),1);if(variantRows.length===1)for(const n of ['price','stock','compare_price'])$('#catalogForm [name='+n+']').value=variantRows[0][n]??'';renderVariants();$('#catalogForm').dispatchEvent(new Event('input',{bubbles:true}));});
 $('#addVariant').onclick=()=>{if(variantRows.length>=100)return notice('At most 100 options.');variantRows.push({variant_values:{},sku:'',price:'',compare_price:'',stock:''});renderVariants();$('#catalogForm').dispatchEvent(new Event('input',{bubbles:true}));};syncVariantBase();
}
function syncVariantBase(){const multiple=variantFields.length&&variantRows.length>1;for(const n of ['price','stock','compare_price']){const input=$('#catalogForm [name='+n+']');if(!input)continue;input.readOnly=!!multiple;input.required=n!=='compare_price'&&!multiple;input.title=multiple?'Calculated from the options below':'Enter '+(n==='stock'?'available stock':'price');if(multiple){input.value=n==='stock'?variantRows.reduce((sum,v)=>sum+(Number(v.stock)||0),0):n==='price'?Math.min(...variantRows.map(v=>Number(v.price)||0)):'';}else if(variantFields.length&&variantRows[0])variantRows[0][n]=input.value;}}
window.readSellerVariants=()=>{if(!variantFields.length&&editing?.product_data?.product_variants?.length)throw Error('Saved variants no longer match this category schema. Contact support before editing.');const rows=SellerToolsModel.variants(variantRows,variantFields);if(rows.reduce((sum,r)=>sum+r.stock,0)>1000000)throw Error('Combined variant stock cannot exceed 1000000.');for(const f of variantFields){const input=document.getElementsByName('attr:'+f.attribute_key)[0];if(input)input.value=rows[0]?.variant_values[f.attribute_key]||'';}syncVariantBase();return rows;};
const baseAddView=views.add;
views.add=async function(){const view=await baseAddView();return {...view,bind(){view.bind();const url=$('#catalogForm [name=image_url]');url.closest('label').hidden=true;url.required=false;url.type='hidden';const upload=$('#photo');upload.onchange=()=>{url.required=false;const old=upload.closest('label').querySelector('.media-preview');if(old)old.remove();if(upload.files[0]){const image=document.createElement('img');image.className='media-preview';image.alt='Selected product photo';const objectURL=URL.createObjectURL(upload.files[0]);image.src=objectURL;image.onload=()=>URL.revokeObjectURL(objectURL);upload.before(image);}};upload.closest('label').classList.add('upload');const text=upload.closest('label').firstChild;if(text.nodeType===3)text.textContent='Upload main product photo';const saved=editing?.product_data?.image_url;if(safeImage(saved)){const img=document.createElement('img');img.className='media-preview';img.src=saved;img.alt='Current product photo';upload.before(img);}const videoLabel=document.createElement('label');videoLabel.className='field full upload';videoLabel.innerHTML='Product video (optional)<input type="file" id="productVideo" accept="video/mp4,video/webm"><small>MP4 or WebM · up to 25 MB</small>';upload.closest('label').after(videoLabel);const oldSubmit=$('#catalogForm').onsubmit;$('#catalogForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter||$('#submitCatalog');button.disabled=true;try{if(!categoryTree.final($('#category').value))throw Error('Choose a final category.');readSellerVariants();if(upload.files[0]&&!['image/jpeg','image/png','image/webp'].includes(upload.files[0].type))throw Error('Use an image for the main product photo.');for(const input of document.querySelectorAll('[data-slot-file]'))if(input.files[0]&&!['image/jpeg','image/png','image/webp'].includes(input.files[0].type))throw Error('Category photos must be images.');for(const f of [upload.files[0],$('#productVideo').files[0],...Array.from(document.querySelectorAll('[data-slot-file]')).map(x=>x.files[0])].filter(Boolean))SellerToolsModel.attachment(f);if(!url.value&&!upload.files[0])throw Error('Upload the main product photo.');for(const input of document.querySelectorAll('[data-slot-file]')){const savedInput=document.getElementsByName(input.dataset.slotFile)[0];if(input.dataset.required==='true'&&!input.files[0]&&!savedInput.value)throw Error('Upload all required category photos.');if(input.files[0]){savedInput.value=(await api.upload(input.files[0])).url;input.value='';}}if(upload.files[0]){url.value=(await api.upload(upload.files[0])).url;upload.value='';url.required=false;}const video=$('#productVideo');if(video.files[0]){const result=await api.upload(video.files[0]);let hidden=$('#videoURL');if(!hidden){hidden=document.createElement('input');hidden.type='hidden';hidden.id='videoURL';hidden.name='video_url';$('#catalogForm').append(hidden);}hidden.value=result.url;video.value='';}button.disabled=false;oldSubmit(e);}catch(err){if(err.status===401){login();return;}$('#formError').textContent=err.message;button.disabled=false;}};}};};
async function bulkCatalog(){await showTool('Bulk product upload',async()=>{const {categories:rows=[]}=await api.categories();const tree=new CeroodCatalog.CategoryTree(rows);$('#modalBody').innerHTML=`<p class="muted">Upload a CSV for one final category. Products are submitted for admin review. Maximum 1000 rows; use individual upload for variant products or categories with required extra photos.</p><label class="field">Category<select id="bulkCategory"><option value="">Choose final category</option>${rows.filter(c=>tree.final(c.id)).map(c=>`<option value="${esc(c.id)}">${esc(tree.path(c.id).map(n=>n.name).join(' › '))}</option>`).join('')}</select></label><div class="toolbar"><button class="btn" id="bulkTemplate">Download CSV template</button><input type="file" id="bulkFile" accept=".csv,text/csv"></div><div id="bulkPreview" role="status"></div><div class="formactions"><button class="btn primary" id="bulkImport" disabled>Submit imported products for review</button></div><details><summary>Previous imports</summary><div id="importHistory"></div></details>`;let parsed=[],fileName='';const selected=()=>{const c=rows.find(c=>String(c.id)===$('#bulkCategory').value);if(!c)throw Error('Choose a final category.');if(c.attributes?.some(a=>a.is_variant===true)||c.image_slots?.some(s=>s.is_required))throw Error('Use individual product upload for this category’s variants or required extra photos.');return c;};$('#bulkCategory').onchange=()=>{parsed=[];$('#bulkFile').value='';$('#bulkImport').disabled=true;$('#bulkPreview').textContent='';};$('#bulkTemplate').onclick=e=>action(e.target,async()=>{const c=selected();csvFile('cerood-product-template.csv',[['supplier_sku','product_name','brand','product_type','selling_price','mrp','stock','description','image_url',...(c.attributes||[]).map(a=>'attr:'+a.attribute_key)],['YOUR-UNIQUE-SKU','Product name','Brand',c.name,'100','120','10','Product description','https://your-image-url',...(c.attributes||[]).map(()=> '')]]);});$('#bulkFile').onchange=async e=>{parsed=[];$('#bulkImport').disabled=true;try{const c=selected(),file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('CSV must be under 5 MB.');fileName=file.name;const raw=SellerToolsModel.parseCSV(await file.text()),seen=new Set();parsed=raw.map((r,i)=>{for(const k of ['supplier_sku','product_name','brand','selling_price','stock','image_url'])if(!String(r[k]||'').trim())throw Error('Row '+(i+2)+': '+k+' is required.');const sku=r.supplier_sku.trim().toLowerCase();if(seen.has(sku))throw Error('Duplicate SKU at row '+(i+2));seen.add(sku);if(!/^https:\/\//i.test(r.image_url)||!Number.isFinite(Number(r.selling_price))||Number(r.selling_price)<=0||!Number.isSafeInteger(Number(r.stock))||Number(r.stock)<0)throw Error('Invalid image URL, price or stock at row '+(i+2));const attrs={};for(const a of c.attributes||[]){const v=r['attr:'+a.attribute_key]||'';if(a.is_required&&!v.trim())throw Error('Row '+(i+2)+': '+a.label+' is required.');if(a.input_type==='number'&&v.trim()&&!Number.isFinite(Number(v)))throw Error('Row '+(i+2)+': '+a.label+' must be a number.');attrs[a.attribute_key]=v;}return {...r,product_type:c.name,product_attributes:attrs};});$('#bulkPreview').innerHTML=`<p>${parsed.length} rows ready. Review before submitting.</p>`+table(['SKU','Product','Price','Stock'],parsed.slice(0,5).map(r=>`<tr><td>${esc(r.supplier_sku)}</td><td>${esc(r.product_name)}</td><td>${money(r.selling_price)}</td><td>${esc(r.stock)}</td></tr>`));$('#bulkImport').disabled=false;}catch(err){$('#bulkPreview').textContent=err.message;}};$('#bulkImport').onclick=e=>action(e.target,async()=>{const c=selected(),batch=SellerToolsModel.uuid(),errors=[];const total=parsed.length;if(!total)throw Error('Choose a CSV first.');let accepted=0;$('#bulkFile').disabled=true;$('#bulkCategory').disabled=true;try{for(let i=0;i<total;i+=250){$('#bulkPreview').textContent='Submitting rows '+(i+1)+'–'+Math.min(i+250,total)+'…';const x=await api.request('/api/sellers/bulk-catalog/import',{method:'POST',body:{marketplace:'general',category_id:c.id,category_leaf:c.name,category_path:tree.path(c.id).map(n=>n.name).join(' > '),file_name:fileName,batch_id:batch,rows:parsed.slice(i,i+250),row_offset:i,final_chunk:i+250>=total}});accepted+=Number(x.chunk?.inserted||0)+Number(x.chunk?.updated||0);errors.push(...(x.chunk?.errors||[]));}parsed=[];$('#bulkPreview').innerHTML=`<p>${accepted} rows accepted/updated. ${errors.length} reported issues.</p>`+table(['Row','SKU','Issue'],errors.map(r=>`<tr><td>${esc(r.row)}</td><td>${esc(r.supplier_sku)}</td><td>${esc(r.error)}</td></tr>`));notice('Import completed. Check the report.');}catch(err){parsed=[];$('#bulkPreview').textContent='Upload stopped: '+err.message+' Check import history before retrying; some rows may already be saved.';}finally{$('#bulkFile').disabled=false;$('#bulkCategory').disabled=false;}});try{const h=await api.request('/api/sellers/bulk-catalog/imports');$('#importHistory').innerHTML=table(['File','Status','Accepted','Rejected'],(h.imports||h.batches||[]).map(x=>`<tr><td>${esc(x.file_name)}</td><td>${pill(x.status)}</td><td>${esc(x.accepted_rows)}</td><td>${esc(x.rejected_rows)}</td></tr>`));}catch{$('#importHistory').textContent='Import history unavailable. Refresh to retry.';}});}
async function priceSchedules(){await showTool('Scheduled discounts',async()=>{const [catalog,result]=await Promise.all([api.products(),api.request('/api/sellers/shop/price-schedules')]);const products=(catalog.products||[]).filter(p=>p.marketplace==='general'&&p.approval_status==='approved'&&p.published_product_id);$('#modalBody').innerHTML=`<p class="muted">Discounts require admin approval. Start at least 5 minutes ahead; duration up to 30 days. Times use your device timezone.</p><form id="priceScheduleForm" class="formgrid"><label class="field full">Published product<select name="product_id" required><option value="">Choose</option>${products.map(p=>`<option value="${esc(p.published_product_id)}">${esc(p.product_data?.name)}</option>`).join('')}</select></label>${field('discount_percent','Discount %','number','', 'required min="1" max="90" step="1"')}${field('starts_at','Starts at','datetime-local','','required')}${field('ends_at','Ends at','datetime-local','','required')}<button class="btn primary">Submit discount for review</button></form><h2 style="margin:24px 0 15px">Schedules</h2>`+table(['Product','Discount','Start / end','Status',''],(result.schedules||[]).map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.discount_percent)}%</td><td>${esc(new Date(p.starts_at).toLocaleString())}<small>${esc(new Date(p.ends_at).toLocaleString())}</small></td><td>${pill(p.status)}</td><td>${['pending','approved'].includes(p.status)?`<button class="btn" data-cancel-schedule="${esc(p.id)}">Cancel</button>`:''}</td></tr>`));$('#priceScheduleForm').onsubmit=e=>{e.preventDefault();action(e.target.querySelector('button'),async()=>{const f=Object.fromEntries(new FormData(e.target));f.starts_at=new Date(f.starts_at).toISOString();f.ends_at=new Date(f.ends_at).toISOString();await api.request('/api/sellers/shop/price-schedules',{method:'POST',body:f});notice('Discount submitted for review.');priceSchedules();});};document.querySelectorAll('[data-cancel-schedule]').forEach(b=>b.onclick=()=>action(b,async()=>{await api.request('/api/sellers/shop/price-schedules/'+encodeURIComponent(b.dataset.cancelSchedule)+'/cancel',{method:'POST'});priceSchedules();}));});}
const baseProducts=views.products;views.products=async()=>{const v=await baseProducts();return {...v,bind(){v.bind();appendActions([['Bulk upload CSV',()=>bulkCatalog()],['Scheduled discounts',priceSchedules]]);}};};
async function pickupLocations(){await showTool('Pickup locations',async()=>{const x=await api.request('/api/sellers/locations'),locations=x.locations||[];$('#modalBody').innerHTML=table(['Location','Address','Default',''],locations.map((p,i)=>`<tr><td>${esc(p.location_name)}</td><td>${esc(p.address_line1)}<small>${esc(p.city)} · ${esc(p.pincode)}</small></td><td>${p.is_default?'Default':`<button class="btn" data-default-location="${i}">Make default</button>`}</td><td><button class="btn" data-delivery-rules="${i}">Delivery rules</button><button class="btn" data-courier-register="${i}">Courier setup</button></td></tr>`))+`<h2 style="margin:25px 0 18px">Add pickup address</h2><form id="pickupForm" class="formgrid">${[['location_name','Location name'],['address_line1','Address line 1'],['address_line2','Address line 2 (optional)'],['city','City'],['district','District'],['state','State'],['pincode','Pincode']].map(([n,l])=>field(n,l,'text','',n==='address_line2'?'':'required')).join('')}<label class="field"><span>Default pickup</span><input type="checkbox" name="is_default"></label><button class="btn primary">Save pickup location</button></form>`;$('#pickupForm').onsubmit=e=>{e.preventDefault();action(e.target.querySelector('button'),async()=>{const f=Object.fromEntries(new FormData(e.target));f.is_default=!!f.is_default;await api.request('/api/sellers/locations',{method:'POST',body:f});notice('Pickup location saved.');pickupLocations();});};document.querySelectorAll('[data-default-location]').forEach(b=>b.onclick=()=>action(b,async()=>{await api.request('/api/sellers/locations/'+encodeURIComponent(locations[Number(b.dataset.defaultLocation)].id)+'/default',{method:'PATCH'});pickupLocations();}));document.querySelectorAll('[data-delivery-rules]').forEach(b=>b.onclick=()=>deliveryRules(locations[Number(b.dataset.deliveryRules)]));document.querySelectorAll('[data-courier-register]').forEach(b=>b.onclick=()=>courierSetup(locations[Number(b.dataset.courierRegister)]));});}
async function deliveryRules(location){await showTool('Delivery rules · '+location.location_name,async()=>{const x=await api.request('/api/sellers/serviceability?fulfilment_location_id='+encodeURIComponent(location.id));$('#modalBody').innerHTML='<p class="muted">Optional destination-pincode overrides. Saving the same pincode updates its existing rule.</p>'+table(['Pincode','Delivery days','Fee','Payment',''],(x.serviceability||[]).map(p=>`<tr><td>${esc(p.destination_pincode)}</td><td>${esc(p.min_delivery_days)}–${esc(p.max_delivery_days)}</td><td>${money(p.delivery_fee)}</td><td>${p.cod_available?'COD ':''}${p.prepaid_available?'Prepaid':''}</td><td><button class="btn" data-remove-rule="${esc(p.id)}">Remove rule</button></td></tr>`))+`<form id="ruleForm" class="formgrid" style="margin-top:22px">${field('destination_pincode','Destination pincode','text','','required pattern="[1-9][0-9]{5}" maxlength="6"')}${field('min_delivery_days','Minimum days','number','1','required min="0" max="90"')}${field('max_delivery_days','Maximum days','number','7','required min="0" max="90"')}${field('delivery_fee','Delivery fee ₹','number','0','required min="0" max="100000" step="0.01"')}<label class="field">COD available<input name="cod" type="checkbox" checked></label><label class="field">Prepaid available<input name="prepaid" type="checkbox" checked></label><button class="btn primary">Save delivery rule</button></form>`;$('#ruleForm').onsubmit=e=>{e.preventDefault();action(e.target.querySelector('button'),async()=>{const f=Object.fromEntries(new FormData(e.target));if(Number(f.max_delivery_days)<Number(f.min_delivery_days))throw Error('Maximum days must be at least the minimum.');await api.request('/api/sellers/serviceability',{method:'POST',body:{...f,fulfilment_location_id:location.id,cod_available:!!f.cod,prepaid_available:!!f.prepaid}});deliveryRules(location);});};document.querySelectorAll('[data-remove-rule]').forEach(b=>b.onclick=()=>{b.textContent='Confirm removal';b.onclick=()=>action(b,async()=>{await api.request('/api/sellers/serviceability/'+encodeURIComponent(b.dataset.removeRule),{method:'DELETE'});deliveryRules(location);});});});}
async function courierSetup(location){modal('Courier pickup setup',`<p>${esc(location.location_name)} · ${esc(location.pincode)}</p><p class="muted">Check pickup coverage first. Registration sends this saved business pickup address to the selected courier.</p><div class="toolbar">${['ekart','delhivery'].map(c=>`<button class="btn" data-check-courier="${c}">Check ${c}</button><button class="btn" data-register-courier="${c}">Register ${c} pickup</button>`).join('')}</div><p id="courierResult" role="status"></p>`);for(const [attr,suffix] of [['checkCourier','serviceability'],['registerCourier','register']])document.querySelectorAll(attr==='checkCourier'?'[data-check-courier]':'[data-register-courier]').forEach(b=>b.onclick=()=>action(b,async()=>{const x=await api.request('/api/sellers/locations/'+encodeURIComponent(location.id)+'/'+b.dataset[attr]+'-'+suffix,{method:'POST'});$('#courierResult').textContent=x.message||'Courier response received. '+JSON.stringify(x.serviceability||x.location?.delhivery||x.location?.ekart||{}); }));}
async function shipments(){await showTool('Shipments',async()=>{const x=await api.request('/api/sellers/workspace/shipments');$('#modalBody').innerHTML=table(['Order','Courier','Tracking','Status'],(x.shipments||[]).map(s=>`<tr><td>${esc(s.order_id)}</td><td>${esc(s.courier)}</td><td>${esc(s.tracking_number||'Pending')}</td><td>${pill(s.tracking_status||s.booking_state)}</td></tr>`))+'<p class="muted">Use an order’s shipping tools to book, refresh or download its label.</p>';});}
