async function bulkInventory(){await showTool('Bulk stock / price update',async()=>{$('#modalBody').innerHTML=`<p class="muted">For existing approved supplier-SKU products. This updates live stock/prices without a new catalog submission. Use individual stock controls for variant inventory.</p><label class="field">Update mode<select id="syncMode"><option value="stock">Stock only</option><option value="price">Price only</option><option value="price_stock">Price and stock</option></select></label><div class="toolbar"><button class="btn" id="syncTemplate">Download template</button><input type="file" id="syncFile" accept=".csv,text/csv"></div><p id="syncPreview" role="status"></p><button class="btn primary" id="syncSubmit" disabled>Apply live inventory update</button>`;let rows=[],fileName='';$('#syncMode').onchange=()=>{rows=[];$('#syncFile').value='';$('#syncSubmit').disabled=true;$('#syncPreview').textContent='';};$('#syncTemplate').onclick=()=>csvFile('cerood-inventory-update.csv',[['supplier_sku','selling_price','mrp','stock']]);$('#syncFile').onchange=async e=>{rows=[];$('#syncSubmit').disabled=true;try{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024)throw Error('Use a CSV under 5 MB.');fileName=f.name;const parsed=SellerToolsModel.parseCSV(await f.text());const seen=new Set(),mode=$('#syncMode').value;for(const [i,r] of parsed.entries()){const sku=String(r.supplier_sku||'').trim().toLowerCase();if(!sku||seen.has(sku))throw Error('Missing or duplicate SKU on row '+(i+2));seen.add(sku);if(mode!=='price'&&(r.stock===''||!Number.isSafeInteger(Number(r.stock))||Number(r.stock)<0))throw Error('Invalid stock on row '+(i+2));if(mode!=='stock'&&(r.selling_price===''||!Number.isFinite(Number(r.selling_price))||Number(r.selling_price)<=0))throw Error('Invalid price on row '+(i+2));}rows=parsed;$('#syncPreview').textContent=rows.length+' rows ready. Check your CSV before applying to live inventory.';$('#syncSubmit').disabled=false;}catch(err){$('#syncPreview').textContent=err.message;}};$('#syncSubmit').onclick=e=>action(e.target,async()=>{if(!rows.length)throw Error('Select a CSV first.');const batch=SellerToolsModel.uuid(),mode=$('#syncMode').value,total=rows.length,issues=[];let updated=0;$('#syncMode').disabled=true;$('#syncFile').disabled=true;try{for(let i=0;i<total;i+=500){const x=await api.request('/api/sellers/bulk-catalog/inventory-update',{method:'POST',body:{mode,batch_id:batch,file_name:fileName,rows:rows.slice(i,i+500),row_offset:i,final_chunk:i+500>=total}});updated+=Number(x.chunk?.updated||0);issues.push(...(x.chunk?.errors||[]));}$('#syncPreview').textContent=updated+' rows updated; '+issues.length+' issues.';if(issues.length)csvFile('cerood-inventory-errors.csv',[['Row','SKU','Issue'],...issues.map(r=>[r.row,r.supplier_sku,r.error])]);}catch(err){$('#syncPreview').textContent='Stopped: '+err.message+' Check live quantities before retrying.';}finally{rows=[];$('#syncMode').disabled=false;$('#syncFile').disabled=false;}});});}
