// Keep native numeric validation and keyboard entry, without spin buttons or
// accidental wheel/arrow changes while scrolling the dashboard.
document.addEventListener('keydown',e=>{if(e.target.matches('input[type=number]')&&['ArrowUp','ArrowDown'].includes(e.key))e.preventDefault();});
document.addEventListener('wheel',e=>{if(e.target===document.activeElement&&e.target.matches('input[type=number]'))e.target.blur();},{passive:true});
